function catalogRows(){const rows=new Map();(window.CINE360_DATA.catalog||[]).forEach(r=>rows.set(r.id,r));items.forEach(r=>rows.set(r.id,r));return [...rows.values()]}
function searchCatalog(query){const q=normalized(query).trim();if(q.length<2)return [];const tokens=q.split(/\s+/);const rank=r=>{const title=normalized(r.title);return title===q?0:title.startsWith(q)?1:title.includes(q)?2:3};return catalogRows().filter(r=>tokens.every(t=>normalized([r.title,r.catalogTitle,r.originalTitle].filter(Boolean).join(' ')).includes(t))).sort((a,b)=>rank(a)-rank(b)||a.title.localeCompare(b.title,'pt-BR')).slice(0,8)}
