function update(id,patch){const r=items.find(x=>x.id===id);if(!r)return;Object.assign(r,patch);if(originals.some(x=>x.id===id)){changes[id]={...(changes[id]||{}),...patch}}else{added=added.map(x=>x.id===id?{...x,...patch}:x)}return persist()}
