function artwork(r,cls=''){const src=safeImageURL(r.poster);if(!src)return `<div class="poster-fallback ${cls}"><span>Maratonenzo</span>${esc(r.title)}</div>`;const n=artCount++;const eager=n<12;return `<img class="${cls}" src="${esc(src)}" alt="Capa de ${esc(r.title)}" loading="${eager?'eager':'lazy'}" decoding="async"${n<8?' fetchpriority="high"':''} referrerpolicy="no-referrer" data-image>`}
const SERIES_TOTALS_KEY='cine360-series-totals-v1';const SERIES_TTL=3*864e5;
let seriesTotals={};try{seriesTotals=JSON.parse(localStorage.getItem(SERIES_TOTALS_KEY)||'{}')||{}}catch{seriesTotals={}}
let seriesBusy=false,seriesRetry=0;
function seriesNeeds(){return items.filter(r=>r.type==='tv'&&!r.hidden&&r.tmdb&&r.status!=='watchlist'&&(!seriesTotals[r.tmdb]||Date.now()-seriesTotals[r.tmdb].at>SERIES_TTL))}
async function hydrateSeriesTotals(){const key=tmdbKey();if(!key||seriesBusy||Date.now()<seriesRetry)return;const queue=[...new Map(seriesNeeds().map(r=>[r.tmdb,r])).values()].slice(0,80);if(!queue.length)return;seriesBusy=true;let changed=false;try{for(const r of queue){const res=await fetch(`https://api.themoviedb.org/3/tv/${r.tmdb}?api_key=${encodeURIComponent(key)}&language=pt-BR`);if(!res.ok){seriesRetry=Date.now()+600000;break}const d=await res.json();const seasons={};(d.seasons||[]).forEach(s=>{const n=Number(s.season_number);if(n>=1&&s.episode_count>0)seasons[n]=s.episode_count});seriesTotals[r.tmdb]={at:Date.now(),ended:['Ended','Canceled'].includes(d.status),seasons};changed=true}}catch{seriesRetry=Date.now()+600000}finally{seriesBusy=false}if(changed){try{localStorage.setItem(SERIES_TOTALS_KEY,JSON.stringify(seriesTotals))}catch{}render()}}
function seriesLineKind(r){if(r.type!=='tv'||r.hidden||r.status==='watchlist'||!r.tmdb)return '';const t=seriesTotals[r.tmdb];if(!t)return '';const nums=Object.keys(t.seasons||{}).map(Number).sort((a,b)=>a-b);if(!nums.length)return '';const last=nums[nums.length-1];const hasEpisodes=(r.seasons||[]).length>0;const watched={};(r.seasons||[]).forEach(s=>{watched[Number(s.number)]=(s.episodes||[]).filter(e=>e.watched!==false).length});const done=n=>hasEpisodes?(watched[n]||0)>=t.seasons[n]:true;const started=hasEpisodes?nums.filter(n=>(watched[n]||0)>0):nums;if(!started.length)return '';const lastStarted=Math.max(...started);if(nums.filter(n=>n<=lastStarted).some(n=>!done(n)))return 'yellow';if(lastStarted<last)return t.ended?'yellow':'green';return t.ended?'blue':'green'}
const SERIES_LINE_LABELS={blue:'Série completa e finalizada',green:'Temporada completa, com temporadas ainda por vir',yellow:'Faltam episódios para terminar'};
function seriesPct(r){const t=seriesTotals[r.tmdb];if(!t)return 0;const totals=t.seasons||{};const total=Object.values(totals).reduce((a,b)=>a+b,0);if(!total)return 0;const watched=Object.keys(totals).reduce((sum,n)=>{const sd=(r.seasons||[]).find(x=>Number(x.number)===Number(n));const c=sd?(sd.episodes||[]).filter(e=>e.watched!==false).length:0;return sum+Math.min(c,totals[n])},0);return Math.max(0,Math.min(100,Math.round(watched/total*100)))}
function seriesLineHTML(r){const k=seriesLineKind(r);if(!k)return '';const label=SERIES_LINE_LABELS[k];if(k==='yellow'){return `<span class="series-line series-track" role="img" aria-label="${label}: ${seriesPct(r)}% assistido" title="${label}: ${seriesPct(r)}% assistido"><span class="series-fill" style="width:${seriesPct(r)}%"></span></span>`}return `<span class="series-line series-${k}" role="img" aria-label="${label}" title="${label}"></span>`}
function card(r){const status=r.status==='history'?'Histórico':statusLabels[r.status]||'Na biblioteca';return `<article class="poster-card"><button class="poster-button" data-open="${esc(r.id)}" aria-label="Ver detalhes de ${esc(r.title)}"><div class="poster-art">${artwork(r)}${selectMode?`<span class="select-mark ${selected.has(r.id)?'on':''}" aria-hidden="true">${selected.has(r.id)?'✓':''}</span>`:''}<span class="poster-bottom ${r.status==='watchlist'?'is-watchlist':''}">${icon(r.status==='watchlist'?'bookmark':'check')}${esc(status)}</span></div>${seriesLineHTML(r)}<div class="card-copy"><h3>${esc(r.title)}</h3><div class="card-meta"><span>${esc(year(r))}</span><span aria-hidden="true">·</span><span>${esc(genres(r)[0]|| (r.type==='tv'?'Série':'Filme'))}</span>${pubRatingHTML(r)}</div></div></button><button class="quick-favorite ${r.favorite?'is-favorite':''}" data-card-favorite="${esc(r.id)}" aria-label="${r.favorite?'Remover':'Adicionar'} ${esc(r.title)} ${r.favorite?'dos':'aos'} favoritos" aria-pressed="${!!r.favorite}">${icon('heart')}</button><button class="card-rating" data-open="${esc(r.id)}" aria-label="Avaliar ${esc(r.title)}">${r.rating?`${stars(r.rating)}<span class="rating-num">${Number(r.rating).toFixed(1)}</span>`:`<span class="rating-help">${icon('star')} Avaliar título</span>`}</button></article>`}
