function trendClick(btn,e){if(btn.hasAttribute('data-top10')){openTop10(btn.dataset.top10);return true}if(btn.hasAttribute('data-trend-open')){openTrend(btn.dataset.trendOpen);return true}if(btn.hasAttribute('data-trend-plat')){dropValues.trendPlatform=btn.dataset.trendPlat;render();return true}if(btn.hasAttribute('data-trend-want')){trendSet(btn.dataset.trendWant,'watchlist');return true}if(btn.hasAttribute('data-trend-seen')){trendSet(btn.dataset.trendSeen,'watched');return true}if(btn.hasAttribute('data-trend-full')){openDetail(items.find(x=>x.id===btn.dataset.trendFull&&!x.hidden)?.id||'');return true}if(!trendOpenId)return false;if(btn.dataset.rate){if(e.detail===0)rateTrend(trendOpenId,Number(btn.dataset.rate));return true}if(btn.hasAttribute('data-clear-rating')){const rid=items.find(x=>x.id===trendOpenId)?.id;if(rid)update(rid,{rating:null});drawTrend(trendOpenId);render();return true}return false}
/* ===== Tendências ao vivo (TMDB, Brasil), recalculadas a cada 6 horas ===== */
const LIVE_TRENDS_KEY='cine360-live-trends-v3';
const LIVE_TTL=6*60*60*1000;
const LIVE_PLATFORMS=[['Netflix',/^netflix$/i],['HBO Max',/^(max|hbo max)$/i],['Disney+',/^disney/i],['Prime Video',/prime video|amazon prime/i],['Paramount+',/paramount/i],['Apple TV',/apple tv/i]];
function liveTrendsCached(){try{const c=JSON.parse(localStorage.getItem(LIVE_TRENDS_KEY)||'null');return c&&c.at&&Date.now()-c.at<LIVE_TTL?c:null}catch{return null}}
function applyLiveTrends(c){if(!c)return;TRENDS.live=true;TRENDS.streaming=c.streaming;TRENDS.rated=c.rated;TRENDS.updated=c.updated;TRENDS.ratedLabel=c.ratedLabel;TRENDS.sources=c.sources;(c.meta||[]).forEach(([key,poster,overview,tmdb,type,backdrop,date])=>{trendPosters[key]=poster;trendMeta[key]={overview,tmdb,type,backdrop:backdrop||'',date:date||''}})}
function ratedNote(x,long){if(x.critics!=null)return long?`Crítica ${x.critics}% · Público ${x.audience}% (Rotten Tomatoes)`:`Crítica ${x.critics}% · Público ${x.audience}%`;const n=String(x.avg).replace('.',',');return long?`Nota TMDB ${n}`:`TMDB ★ ${n}`}
let liveBusy=false,liveRetry=0;
async function hydrateLiveTrends(){const key=tmdbKey();if(!key||liveBusy||liveTrendsCached()||Date.now()<liveRetry)return;liveBusy=true;try{
  const api=async(path,params='')=>{const res=await fetch(`https://api.themoviedb.org/3/${path}?api_key=${encodeURIComponent(key)}&language=pt-BR&watch_region=BR${params}`);if(!res.ok)throw new Error('tmdb');return (await res.json()).results||[]};
  const year=new Date().getFullYear();const meta=[];
  const take=(list,type)=>list.filter(r=>r.name||r.title).slice(0,10).map(r=>{const t=r.name||r.title;meta.push([normalized(t),r.poster_path?`https://image.tmdb.org/t/p/w500${r.poster_path}`:'',r.overview||'',r.id,type,r.backdrop_path?`https://image.tmdb.org/t/p/w1280${r.backdrop_path}`:'',(r.release_date||r.first_air_date||'')]);return t});
  const providers=await api('watch/providers/tv');
  const found=LIVE_PLATFORMS.map(([name,re])=>{const p=providers.find(x=>re.test(x.provider_name||''));return p?{platform:name,id:p.provider_id}:null}).filter(Boolean);
  const streaming=await Promise.all(found.map(async g=>{const q=`&with_watch_providers=${g.id}&with_watch_monetization_types=flatrate&sort_by=popularity.desc`;const [tv,movie]=await Promise.all([api('discover/tv',q),api('discover/movie',q)]);return {platform:g.platform,tv:take(tv,'tv'),movie:take(movie,'movie')}}));
  const best=await api('discover/movie',`&sort_by=vote_average.desc&vote_count.gte=300&primary_release_year=${year}`);
  const rated=best.filter(r=>r.title&&r.poster_path).slice(0,8).map(r=>{meta.push([normalized(r.title),`https://image.tmdb.org/t/p/w500${r.poster_path}`,r.overview||'',r.id,'movie',r.backdrop_path?`https://image.tmdb.org/t/p/w1280${r.backdrop_path}`:'']);return {title:r.title,critics:null,audience:null,avg:Number(r.vote_average).toFixed(1)}});
  if(!streaming.some(g=>g.tv.length||g.movie.length)||!rated.length)throw new Error('empty');
  const data={at:Date.now(),updated:new Date().toLocaleDateString('pt-BR',{timeZone:'America/Sao_Paulo'}),ratedLabel:`TMDB, filmes de ${year} mais bem avaliados`,streaming,rated,meta,sources:[['TMDB: popularidade por plataforma no Brasil','https://www.themoviedb.org/'],[`TMDB: filmes de ${year} mais bem avaliados`,'https://www.themoviedb.org/']]};
  try{localStorage.setItem(LIVE_TRENDS_KEY,JSON.stringify(data))}catch{}
  applyLiveTrends(data);heroRandomStart();if(view==='trends'||view==='home')render();
}catch{liveRetry=Date.now()+600000}finally{liveBusy=false}}
applyLiveTrends(liveTrendsCached());
let trendHydrating=false;
async function hydrateTrendPosters(){const key=tmdbKey();if(!key||trendHydrating)return;const pending=[...trendMerged().values()].filter(e=>(trendPosters[e.key]===undefined||trendMeta[e.key]===undefined)&&!(trendCatalogByTitle().get(e.key)||{}).poster&&!items.some(r=>normalized(r.title)===e.key&&r.poster));if(!pending.length)return;trendHydrating=true;let changed=false,lastPaint=0;const save=()=>{try{localStorage.setItem(TREND_POSTER_KEY,JSON.stringify(trendPosters));localStorage.setItem('cine360-trend-meta',JSON.stringify(trendMeta))}catch{}};const lookup=async e=>{const res=await fetch(`https://api.themoviedb.org/3/search/multi?api_key=${encodeURIComponent(key)}&language=pt-BR&query=${encodeURIComponent(e.title)}`);if(!res.ok)throw new Error('tmdb');const data=await res.json();const hit=(data.results||[]).find(x=>(x.media_type==='movie'||x.media_type==='tv')&&x.poster_path);trendPosters[e.key]=hit?`https://image.tmdb.org/t/p/w500${hit.poster_path}`:'';trendMeta[e.key]=hit?{overview:hit.overview||'',tmdb:hit.id,type:hit.media_type}:{overview:'',tmdb:null,type:''};changed=true};const queue=pending.slice(0,120);let failed=false;const worker=async()=>{while(queue.length&&!failed){const e=queue.shift();try{await lookup(e)}catch{failed=true;break}if(Date.now()-lastPaint>700){lastPaint=Date.now();save();if(view==='trends')render()}}};try{await Promise.all(Array.from({length:6},worker))}finally{trendHydrating=false}if(changed){save();if(view==='trends')render()}}
function warmPosters(){const seen=new Set(),urls=[];const add=r=>{const u=safeImageURL(r.poster);if(u&&u.startsWith('https://')&&!seen.has(u)){seen.add(u);urls.push(u)}};const live=items.filter(r=>!r.hidden);live.filter(r=>r.status==='watchlist').forEach(add);trendAll().forEach(add);live.forEach(add);let i=0;const next=()=>{if(i>=Math.min(urls.length,220))return;const img=new Image();img.decoding='async';img.referrerPolicy='no-referrer';img.onload=img.onerror=next;img.src=urls[i++]};for(let k=0;k<6;k++)next()}
window.addEventListener('load',()=>setTimeout(warmPosters,400));
function tmdbKeyBox(always=false){if(TRENDS.tmdbKey||(tmdbKey()&&!always))return '';const saved=!!tmdbKey();return `<form class="tmdb-box" data-tmdb-form><div><strong>Capas de todos os títulos</strong>${saved?'<p>Chave salva neste navegador. Cole outra para trocar.</p>':'<p>Cole sua chave gratuita da API do TMDB. Ela fica salva só neste navegador, não no site.</p>'}</div><div class="tmdb-row"><input name="key" type="password" autocomplete="off" placeholder="Chave da API do TMDB (API Key v3)" aria-label="Chave da API do TMDB" required><button class="primary" type="submit">Salvar chave</button></div></form>`;}
function trends(){const map=trendMerged();const all=[...map.values()];const sel=dropValues.trendPlatform||'all';const platforms=TRENDS.streaming.map(g=>g.platform);const entries=all.filter(e=>sel==='all'||e.platforms.includes(sel));const rowsOf=t=>entries.filter(e=>e.type===t).map(trendRow);const tvRows=rowsOf('tv'),movieRows=rowsOf('movie');const countOf=p=>all.filter(e=>e.platforms.includes(p)).length;const tiles=[['all','Todas',all.length,'#cfac6a'],...platforms.map(p=>[p,p,countOf(p),PLAT_COLOR[p]])];const strip=`<div class="plat-strip" role="group" aria-label="Destacar plataforma">${tiles.map(([v,l,n,c])=>`<button type="button" class="plat-tile" data-trend-plat="${esc(v)}" aria-pressed="${sel===v}" style="--plat:${c||'#6b6878'}"><strong>${esc(l)}</strong><span>${n} ${n===1?'título':'títulos'}</span></button>`).join('')}</div>`;const section=(label,list)=>`<section class="section up-section"><h2 class="up-type">${label}<span>${list.length} ${list.length===1?'título':'títulos'}</span></h2><div class="up-grid">${list.map(r=>trendCard(r)).join('')}</div></section>`;const rated=TRENDS.rated.map(x=>({x,row:trendRow(map.get(normalized(x.title)))}));const src=TRENDS.sources.map(([l,u])=>`<a href="${esc(safeURL(u))}" target="_blank" rel="noopener">${esc(l)}</a>`).join(' · ');hydrateLiveTrends();hydrateTrendPosters();const keyBox=tmdbKeyBox();return `${heading('Tendências','O que está em alta nas plataformas e o que a crítica tem aplaudido, para escolher a próxima sessão.','O QUE ESTÁ EM ALTA')}${keyBox}${strip}${section('Séries em alta',tvRows)}${section('Filmes em alta',movieRows)}<section class="section up-section"><h2 class="up-type">Bem avaliados<span>${TRENDS.ratedLabel||'Rotten Tomatoes, lista de 2026'}</span></h2><div class="up-grid">${rated.map(({x,row})=>trendCard(row,`<span>${ratedNote(x)}</span>`)).join('')}</div></section><p class="source-note">Fontes: ${src}. ${TRENDS.live?`Atualizado em ${TRENDS.updated}, com dados do TMDB recalculados a cada 6 horas.`:`Atualizado em ${TRENDS.updated} com rankings das ${esc(TRENDS.weeks)}. O IMDb não estava acessível nesta atualização, então a seleção vem de rankings de streaming e da Rotten Tomatoes.`}</p>`}

let choiceType='all';
function choiceTypeHTML(){const opts=[['all','Tudo'],['movie','Filmes'],['tv','Séries']];return `<div class="choice-type" role="group" aria-label="Tipo de título">${opts.map(([v,l])=>`<button type="button" data-choice-type="${v}" aria-pressed="${choiceType===v}">${l}</button>`).join('')}</div>`}
const foldOpen={};const statFold=(key,title,body)=>{const def=!window.matchMedia('(max-width:760px)').matches;const o=key in foldOpen?foldOpen[key]:def;return `<details class="stats-card stats-fold" data-fold="${key}"${o?' open':''}><summary><h3>${title}</h3></summary>${body}</details>`};
document.addEventListener('toggle',e=>{const d=e.target;if(d&&d.matches&&d.matches('.stats-fold'))foldOpen[d.dataset.fold]=d.open},true);
function statsHTML(){const vis=items.filter(r=>!r.hidden&&(r.status==='watched'||r.status==='history'));if(!vis.length)return '';const minutes=vis.reduce((n,r)=>{if(r.type==='tv'){const eps=(r.seasons||[]).reduce((m,se)=>m+(se.episodes||[]).filter(e=>e.watched!==false).length,0);return n+eps*(r.runtime||0)}return n+(r.runtime||0)},0);const hours=Math.round(minutes/60);const yearsMap={};vis.forEach(r=>{const y=String(r.release_date||'').slice(0,4)||String(r.year||'');if(/^\d{4}$/.test(y))yearsMap[y]=(yearsMap[y]||0)+1});const years=Object.entries(yearsMap).sort((a,b)=>a[0]-b[0]).slice(-12);const maxY=Math.max(1,...years.map(([,n])=>n));const gMap={};vis.forEach(r=>genres(r).forEach(g=>{gMap[g]=(gMap[g]||0)+1}));const gens=Object.entries(gMap).sort((a,b)=>b[1]-a[1]).slice(0,5);const maxG=Math.max(1,...gens.map(([,n])=>n));const rated=vis.filter(r=>r.rating);const avg=rated.length?(rated.reduce((n,r)=>n+Number(r.rating),0)/rated.length).toFixed(1).replace('.',','):'—';const bars=(list,max)=>list.map(([k,n])=>`<div class="bar-row"><span>${esc(k)}</span><div class="bar"><i style="width:${Math.round(n/max*100)}%"></i></div><b>${n}</b></div>`).join('');return `<section class="section stats-panel" aria-label="Seu cinema em números"><span class="eyebrow">SEU CINEMA EM NÚMEROS</span><div class="stats-kpis"><div><strong>${hours.toLocaleString('pt-BR')}</strong><span>horas assistidas (estimado)</span></div><div><strong>${vis.length.toLocaleString('pt-BR')}</strong><span>títulos concluídos</span></div><div><strong>${avg}</strong><span>sua nota média</span></div></div><div class="stats-grid">${statFold('years','Títulos por ano',years.length?bars(years,maxY):'<p class="muted">Sem anos informados.</p>')}${statFold('genres','Gêneros mais vistos',gens.length?bars(gens,maxG):'<p class="muted">Sem gêneros informados.</p>')}</div></section>`}
function backupNudge(){const items_=items.filter(r=>!r.hidden&&(r.status==='watched'||r.status==='history'));if(!items_.length)return '';let last=0,snooze=0;try{last=Date.parse(localStorage.getItem('cine360-last-backup')||'')||0;snooze=Number(localStorage.getItem('cine360-backup-snooze')||0)}catch{}if(Date.now()<snooze)return '';if(last&&Date.now()-last<7*864e5)return '';return `<div class="backup-nudge" role="status"><span>${last?'Faz mais de uma semana desde o último backup.':'Você ainda não exportou um backup.'} Sua biblioteca fica salva só neste navegador.</span><div class="backup-actions"><button class="secondary" data-backup>Exportar agora</button><button class="subtle-button" data-dismiss-backup>Lembrar depois</button></div></div>`}
let heroBdBusy=false,heroBdRetry=0;
async function hydrateHeroBackdrops(){const key=tmdbKey();if(!key||heroBdBusy||Date.now()<heroBdRetry)return;const queue=[...new Set(trendAll().map(r=>normalized(r.title)))].filter(k=>trendMeta[k]&&trendMeta[k].tmdb&&trendMeta[k].type&&trendMeta[k].bd===undefined);if(!queue.length)return;heroBdBusy=true;let changed=false;try{for(const k of queue.slice(0,80)){const m=trendMeta[k];const res=await fetch(`https://api.themoviedb.org/3/${m.type}/${m.tmdb}?api_key=${encodeURIComponent(key)}&language=pt-BR`);if(!res.ok){heroBdRetry=Date.now()+600000;break}const d=await res.json();trendMeta[k]={...m,bd:1,backdrop:d.backdrop_path?`https://image.tmdb.org/t/p/w1280${d.backdrop_path}`:''};changed=true}}catch{heroBdRetry=Date.now()+600000}finally{heroBdBusy=false}if(changed){try{localStorage.setItem('cine360-trend-meta',JSON.stringify(trendMeta))}catch{}if(view==='home')render()}}
function nextEpisode(r){const t=r.tmdb&&seriesTotals[r.tmdb];if(!t)return null;const nums=Object.keys(t.seasons||{}).map(Number).sort((a,b)=>a-b);for(const n of nums){const sd=(r.seasons||[]).find(x=>Number(x.number)===n);const seen=new Set((sd&&sd.episodes||[]).filter(e=>e.watched!==false).map(e=>Number(e.number)));for(let k=1;k<=t.seasons[n];k++){if(!seen.has(k))return {season:n,episode:k}}}return null}
function lastEpisodeAt(r){let m='';(r.seasons||[]).forEach(s=>(s.episodes||[]).forEach(e=>{if(e.watched!==false&&e.addedDate&&e.addedDate>m)m=e.addedDate}));return m}
function continueRows(){return items.filter(r=>r.type==='tv'&&!r.hidden&&r.status!=='watchlist'&&seriesLineKind(r)==='yellow'&&countEpisodes(r)>0).map(r=>({r,next:nextEpisode(r),at:lastEpisodeAt(r)})).filter(x=>x.next).sort((a,b)=>b.at.localeCompare(a.at)).slice(0,8)}
function continueHTML(){const rows=continueRows();if(!rows.length)return '';return `<section class="section">${header('Continue de onde parou','Calculado automaticamente a partir dos episódios que você já marcou.')}<div class="cw-row">${rows.map(({r,next})=>{const pct=seriesPct(r);const img=safeImageURL(r.backdrop||r.poster);return `<article class="cw-card"><button type="button" class="cw-art" data-open="${esc(r.id)}" aria-label="Abrir ${esc(r.title)}">${img?`<img src="${esc(img)}" alt="" loading="lazy" referrerpolicy="no-referrer" onerror="this.remove()">`:''}<span class="cw-badge">T${next.season} · E${next.episode}</span></button><div class="cw-body"><strong class="cw-title">${esc(r.title)}</strong><span class="cw-next">Próximo: temporada ${next.season}, episódio ${next.episode}</span><span class="cw-bar" aria-hidden="true"><span style="width:${pct}%"></span></span><span class="cw-pct">${pct}% da série assistida</span><button type="button" class="cw-mark" data-next-ep="${esc(r.id)}|${next.season}|${next.episode}">${icon('check')} Marcar E${next.episode} como visto</button></div></article>`}).join('')}</div></section>`}
function markNextEpisode(id,season,episode){const r=items.find(x=>x.id===id);if(!r)return;const seasons=structuredClone(r.seasons||[]);let sObj=seasons.find(x=>Number(x.number)===season);if(!sObj){sObj={number:season,episodes:[]};seasons.push(sObj);seasons.sort((a,b)=>a.number-b.number)}let ep=sObj.episodes.find(x=>Number(x.number)===episode);if(!ep){ep={number:episode,addedDate:new Date().toISOString()};sObj.episodes.push(ep);sObj.episodes.sort((a,b)=>a.number-b.number)}ep.watched=true;ep.addedDate=new Date().toISOString();update(id,{seasons});toast(`${r.title}: T${season} · E${episode} marcado como visto.`);render()}
function home(){hydrateLiveTrends();hydrateHeroBackdrops();const visible=items.filter(r=>!r.hidden),films=visible.filter(r=>r.type==='movie'&&r.status==='watched').length,series=visible.filter(r=>r.type==='tv'&&r.status!=='watchlist').length,watch=visible.filter(r=>r.status==='watchlist'),rated=visible.filter(r=>r.rating),watching=visible.filter(r=>r.status==='watching');const feature=visible.find(r=>r.id==='movie-438631')||visible[0];const wishes=[...watch].sort((a,b)=>(b.priority||0)-(a.priority||0)||Number(!!b.poster)-Number(!!a.poster)).slice(0,6);const backdrop=feature&&(window.CINE360_DATA.hero||feature.backdrop||feature.poster);return `<div class="greeting"><div><h1>${greetingLine()}</h1><p>Qual a boa de hoje?</p></div><div class="greeting-side"><span class="today"><i></i> Seu cinema particular</span>${levelPill()}</div></div>${backupNudge()}<div class="home-stage">${heroSlide()}<aside class="session-card"><div class="session-heading"><span class="eyebrow">SEM INDECISÃO</span>${icon('shuffle')}</div><h2>O difícil é escolher.<br><em>Deixa com a gente.</em></h2><p>Um título da sua lista, escolhido para o clima da sessão.</p><div class="poster-fan" aria-hidden="true" data-fan>${fanHTML()}</div>${choiceTypeHTML()}<button class="session-action" data-choice>${icon('shuffle')} Escolher por mim ${icon('arrow')}</button><span class="session-footnote">${watch.length} histórias esperando pelo play</span></aside></div><div class="stats">${[[films,'Filmes assistidos','film','library','movie'],[series,'Séries acompanhadas','library','library','tv'],[watch.length,'Na sua lista','bookmark','watchlist',''],[rated.length,'Títulos avaliados','star','library','']].map(([n,label,ic,v,t])=>`<button class="stat" data-view="${v}" ${t?`data-type="${t}"`:''}><span class="stat-icon">${icon(ic)}</span><span><strong>${n}</strong><span class="stat-label">${label}</span></span>${icon('arrow')}</button>`).join('')}</div>${statsHTML()}${continueHTML()}${watching.length?`<section class="section">${header('Seu próximo episódio','As séries que você marcou como assistindo.','<button class="text-btn" data-view="library" data-type="watching">Ver todas →</button>')}${grid(watching.slice(0,6))}</section>`:''}${top10HTML()}<section class="section">${header('Na sua próxima sessão','Sua lista de desejos. Uma indicação nunca mais fica pelo caminho.','<button class="text-btn" data-view="watchlist">Ver minha lista '+icon('arrow')+'</button>')}${wishes.length?grid(wishes,'home-featured'):empty('Salve filmes e séries para sua próxima sessão.')}</section><section class="section">${header('Universos para explorar','Suas coleções, com todas as histórias no mesmo lugar.')}<div class="collection-grid">${[['Marvel','movie-299536','Universo Marvel','Heróis. Encontros. Infinitas possibilidades.'],['Batman','movie-414906','Gotham & Batman','Toda cidade tem as suas sombras.'],['StarWars','movie-140607','Universo Star Wars','Uma galáxia muito distante, a um clique de distância.'],['HarryPotter','movie-671','Universo Harry Potter','Magia, castelos e amizades para a vida toda.']].filter(([v])=>visible.some(r=>(r.collections||[]).includes(v))).map(([v,id,title,desc])=>{const r=items.find(x=>x.id===id);return `<button class="collection-card ${v.toLowerCase()}" data-view="${v}">${r?.backdrop?`<img src="${esc(safeImageURL(r.backdrop))}" alt="" loading="lazy" referrerpolicy="no-referrer">`:''}<span class="collection-content"><small>${visible.filter(r=>(r.collections||[]).includes(v)).length} TÍTULOS NA COLEÇÃO</small><strong>${title}</strong><span>${desc}</span></span><span class="collection-arrow">${icon('arrow')}</span></button>`}).join('')}</div></section>`}
function getList(){let list=items.filter(r=>!r.hidden);if(dropValues.libPlatform&&dropValues.libPlatform!=='all'){const idx=platformIndex();list=list.filter(r=>(idx.get(normalized(r.title))||[]).includes(dropValues.libPlatform))}if(view==='library')list=list.filter(r=>r.status==='watched'||r.status==='history');if(view==='library'&&filter!=='unrated')list=list.filter(r=>r.rating);if(view==='watchlist')list=list.filter(r=>r.status==='watchlist');if(view==='favorites')list=list.filter(r=>r.favorite);if(COLLECTIONS.includes(view))list=list.filter(r=>(r.collections||[]).includes(view));if(filter==='movie'||filter==='tv')list=list.filter(r=>r.type===filter);if(filter==='watching')list=list.filter(r=>r.status==='watching');if(filter==='unrated')list=list.filter(r=>!r.rating);if(genreFilter!=='all')list=list.filter(r=>genres(r).includes(genreFilter));if(search)list=list.filter(r=>normalized(r.title+' '+genres(r).join(' ')).includes(normalized(search)));if(sort==='sofa')list.sort((a,b)=>sofaPos(a)-sofaPos(b));else if(sort==='title')list.sort((a,b)=>a.title.localeCompare(b.title,'pt-BR'));else if(sort==='rating')list.sort((a,b)=>(b.rating||0)-(a.rating||0));else if(sort==='recent')list.sort((a,b)=>(b.addedDate||'').localeCompare(a.addedDate||'')||sofaPos(a)-sofaPos(b));else if(sort==='priority')list.sort((a,b)=>(b.priority||0)-(a.priority||0));else list=prioritize(list);return list}
function dropMenu(key,label,options,current,end=false){const cur=options.find(o=>o[0]===current)||options[0];const open=openMenu===key;return `<div class="drop-menu${end?' end':''}${open?' open':''}" data-drop-root="${key}"><button type="button" class="drop-trigger" aria-haspopup="listbox" aria-expanded="${open}" data-drop-toggle="${key}"><span>${esc(label)}: <b>${esc(cur[1])}</b></span>${icon('arrow')}</button>${open?`<div class="drop-panel" role="listbox" aria-label="${esc(label)}">${options.map(([v,l])=>`<button type="button" role="option" aria-selected="${v===current}" class="${v===current?'selected':''}" data-drop-key="${key}" data-drop-value="${esc(v)}">${esc(l)}</button>`).join('')}</div>`:''}</div>`}
