let calDay=null;
const CAL_KEY='cine360-calendar-v1';
const CAL_TTL=12*3600*1000;
const calCache={};
const calBusy={};
let calRetry=0;
function calStored(ym){try{const s=JSON.parse(localStorage.getItem(CAL_KEY)||'{}');const e=s[ym];return e&&Date.now()-e.at<CAL_TTL?e.events:null}catch{return null}}
function calSave(ym,events){try{const s=JSON.parse(localStorage.getItem(CAL_KEY)||'{}');s[ym]={at:Date.now(),events};localStorage.setItem(CAL_KEY,JSON.stringify(s))}catch{}}
function calLive(ym){if(calCache[ym])return calCache[ym];const stored=calStored(ym);if(stored){calCache[ym]=stored;return stored}return null}
async function hydrateCalendar(){
  const key=tmdbKey();if(!key||view!=='calendar')return;
  const y=month.getFullYear(),m=month.getMonth(),ym=`${y}-${String(m+1).padStart(2,'0')}`;
  if(calLive(ym)||calBusy[ym]||Date.now()<calRetry)return;
  calBusy[ym]=true;
  try{
    const from=`${ym}-01`,to=`${ym}-${String(new Date(y,m+1,0).getDate()).padStart(2,'0')}`;
    const get=async(path,params)=>{const res=await fetch(`https://api.themoviedb.org/3/${path}?api_key=${encodeURIComponent(key)}&language=pt-BR&region=BR${params}`);if(!res.ok)throw new Error('tmdb');return (await res.json()).results||[]};
    const [movies,shows]=await Promise.all([
      get('discover/movie',`&with_release_type=2|3&release_date.gte=${from}&release_date.lte=${to}&sort_by=popularity.desc`),
      get('discover/tv',`&first_air_date.gte=${from}&first_air_date.lte=${to}&sort_by=popularity.desc`)
    ]);
    const events=[
      ...movies.filter(r=>r.title&&String(r.release_date||'').startsWith(ym)).map(r=>({day:Number(r.release_date.slice(8,10)),type:'cinema',title:r.title,note:'',provider:'Cinema'})),
      ...shows.filter(r=>r.name&&String(r.first_air_date||'').startsWith(ym)).map(r=>({day:Number(r.first_air_date.slice(8,10)),type:'stream',title:r.name,note:'Estreia de série',provider:'Série'}))
    ];
    calCache[ym]=events;calSave(ym,events);
    if(view==='calendar')render();
  }catch{calRetry=Date.now()+600000}finally{calBusy[ym]=false}
}
function calendar(){const y=month.getFullYear(),m=month.getMonth(),start=(new Date(y,m,1).getDay()+6)%7,total=new Date(y,m+1,0).getDate();const monthName=new Intl.DateTimeFormat('pt-BR',{month:'long'}).format(month);const calKey=`${y}-${String(m+1).padStart(2,'0')}`;const curated=releases.map(([day,type,title,note])=>({day,type,title,note,provider:type==='stream'?'Netflix':'Cinema'})).filter(()=>y===2026&&m===9);const liveEvents=calLive(calKey)||[];const seenTitles=new Set(curated.map(e=>normalized(e.title)));const events=[...curated,...liveEvents.filter(e=>!seenTitles.has(normalized(e.title)))];const calDesc=tmdbKey()?'Estreias de cinema e séries pelo TMDB, na região Brasil, e lançamentos de streaming selecionados à mão.':'Lançamentos de streaming selecionados à mão. Cole a chave do TMDB em Tendências para ver estreias de cinema e séries de todos os meses.';const platformOptions=[['all','Todas as plataformas'],['Netflix','Netflix'],['Prime Video','Prime Video'],['HBO Max','HBO Max'],['Apple TV','Apple TV'],['Disney+','Disney+'],['Globoplay','Globoplay']];const visible=e=>(calendarFilter==='all'||calendarFilter===e.type||(calendarFilter==='mine'&&items.some(r=>normalized(r.title)===normalized(e.title)&&r.status==='watchlist')))&&(!calendar.platform||calendar.platform==='all'||e.provider===calendar.platform);const dayEvents=d=>events.filter(e=>e.day===d&&visible(e));const ownOf=e=>items.find(r=>normalized(r.title)===normalized(e.title)&&!r.hidden);const eventRow=e=>{const own=ownOf(e);const inner=`<span class="cal-row-title">${esc(e.title)}</span><span class="cal-row-meta">${esc(e.provider)}${e.note?' · '+esc(e.note):''}</span>`;return own?`<li><button class="cal-row ${e.type==='stream'?'stream':''}" data-open="${esc(own.id)}">${inner}<span class="cal-row-open">Abrir ${icon('arrow')}</span></button></li>`:`<li><div class="cal-row ${e.type==='stream'?'stream':''}">${inner}</div></li>`};const selected=calDay&&calDay<=total?calDay:null;const panel=selected?(()=>{const list=dayEvents(selected);return `<section class="day-panel" aria-live="polite"><div class="day-panel-head"><h3>${selected} de ${esc(monthName)}</h3><span class="day-panel-count">${list.length} ${list.length===1?'lançamento':'lançamentos'}</span><button class="text-btn" data-cal-day-close>Fechar ✕</button></div>${list.length?`<ul class="day-panel-list">${list.map(eventRow).join('')}</ul>`:'<p class="muted">Nenhum lançamento para este dia com os filtros atuais.</p>'}</section>`})():'';return `${heading('Calendário de lançamentos',calDesc,'RESERVE A PRÓXIMA SESSÃO')}<div class="filter-bar">${[['all','Todos'],['cinema','Cinema'],['stream','Streaming'],['mine','Minha lista']].map(([id,l])=>`<button data-calfilter="${id}" aria-pressed="${calendarFilter===id}" class="${calendarFilter===id?'selected':''}">${l}</button>`).join('')}${dropMenu('platform','Plataforma',platformOptions,calendar.platform||'all',true)}</div><div class="calendar-head"><button data-month="-1" aria-label="Mês anterior">←</button><h2>${esc(monthName)} de ${y}</h2><button data-month="1" aria-label="Próximo mês">→</button></div><div class="calendar-grid">${['SEG','TER','QUA','QUI','SEX','SÁB','DOM'].map(d=>`<div class="weekday">${d}</div>`).join('')}${Array.from({length:Math.ceil((start+total)/7)*7},(_,i)=>{const day=i-start+1,valid=day>0&&day<=total;if(!valid)return '<div class="calendar-cell off"></div>';const ev=dayEvents(day);const shown=ev.slice(0,2);const more=ev.length-shown.length;const isToday=day===7&&m===9&&y===2026;return `<button type="button" class="calendar-cell day-cell ${isToday?'today':''} ${selected===day?'selected':''}" data-cal-day="${day}" aria-pressed="${selected===day}" aria-label="Dia ${day}: ${ev.length} lançamento${ev.length===1?'':'s'}"><span class="day-number">${day}</span>${shown.map(e=>`<span class="cal-chip ${e.type==='stream'?'stream':''}">${esc(e.title)}</span>`).join('')}${more>0?`<span class="cal-more">+${more} ${more===1?'título':'títulos'}</span>`:''}</button>`}).join('')}</div>${panel}<p class="source-note">Fontes: cinema — Showmetech e Cenanauta (datas conferidas com Ingresso.com); streaming — Omelete (Netflix). Quando as fontes divergem, usamos a data da Showmetech. Títulos com data incerta em uma das fontes: Razão e Sensibilidade, Três Horas para Viver e Sacrifício. IMDb e Rotten Tomatoes não puderam ser lidos automaticamente; o Rotten Tomatoes lista datas dos EUA.</p><div class="calendar-legend"><b>● Cinema</b><i>● Streaming</i><span>Toque em um dia para ver todos os lançamentos</span></div>`}
let lastMainHTML=null;
function render(){artCount=0;const page=view==='home'&&!search?home():view==='calendar'?calendar():view==='upcoming'?upcoming():view==='trends'?trends():view==='releases'?releasesView():library();hydrateRatings();hydrateTop10();if(view==='calendar')hydrateCalendar();hydrateSeriesTotals();const mainHTML=(window.CINE360_DATA.release!==RELEASE?'<p class="demo-notice" role="status">O catálogo desta página está desatualizado. Para carregar as sinopses desta edição, substitua também o arquivo biblioteca.js enviado com a atualização.</p>':'')+(!tmdbKey()&&(view==='library'||view==='watchlist')?'<p class="demo-notice tmdb-hint" role="status">Quer ver a nota média pública de cada título? Cole sua chave do TMDB na página <button type="button" class="text-btn" data-view="trends">Tendências</button>.</p>':'')+page;if(mainHTML!==lastMainHTML){lastMainHTML=mainHTML;$('#main').innerHTML=mainHTML;fixImages();$$('[data-platform-logo]',$('#main')).forEach(img=>img.addEventListener('error',()=>{const t=document.createElement('span');t.className='platform-text';t.textContent=img.dataset.name||'';img.replaceWith(t)},{once:true}))}$('#breadcrumb').textContent=labels[view]||'Busca';if(view==='calendar'&&$('#platform'))$('#platform').value=calendar.platform||'all';$('#libraryCount').textContent=items.filter(r=>!r.hidden&&(r.status==='watched'||r.status==='history')).length;$('#watchCount').textContent=items.filter(r=>r.status==='watchlist'&&!r.hidden).length;['#libraryCount','#watchCount'].forEach(sel=>{const el=$(sel);if(!el)return;const v=el.textContent;if(el.dataset.last!==undefined&&el.dataset.last!==v){el.classList.remove('bump');void el.offsetWidth;el.classList.add('bump')}el.dataset.last=v});$('#moreBtn')?.classList.toggle('has-active',['calendar','upcoming','releases'].includes(view));$$('[data-collection-nav]', $('.sidebar')).forEach(b=>{b.hidden=!items.some(r=>!r.hidden&&(r.collections||[]).includes(b.dataset.collectionNav))});$$('[data-view]', $('.sidebar')).forEach(b=>{b.classList.toggle('active',b.dataset.view===view);if(b.dataset.view===view)b.setAttribute('aria-current','page');else b.removeAttribute('aria-current')}); }
function fixImages(root=document){$$('[data-image]',root).forEach(img=>img.addEventListener('error',()=>{const r=items.find(x=>`Capa de ${x.title}`===img.alt);const fallback=document.createElement('div');fallback.className='poster-fallback '+(img.classList.contains('detail-poster')?'detail-poster':'');fallback.innerHTML=`<span>Maratonenzo</span>${esc(r?.title||'Capa indisponível')}`;img.replaceWith(fallback)},{once:true}))}
function navigate(next,type){$('.sidebar').classList.remove('more-open');$('#moreBtn')?.setAttribute('aria-expanded','false');view=next;heroElapsed=0;sort=next==='library'?'recent':'sofa';filter=type||'all';search='';genreFilter='all';dropValues.libPlatform='all';selectMode=false;selected.clear();$('#search').value='';limit=30;render();window.scrollTo({top:0,behavior:'instant'});const mv=$('#main');if(mv){mv.classList.remove('view-enter');void mv.offsetWidth;mv.classList.add('view-enter')}}
function ratingPicker(r){return `<div class="rating-picker" aria-label="Sua avaliação, em dez estrelas">${starParts(r.rating).map((w,i)=>`<span class="rating-star" aria-hidden="false">☆<span class="star-fill" style="width:${w}%" aria-hidden="true">★</span><button type="button" class="half-control left" data-rate="${i+.5}" aria-label="Avaliar com ${String(i+.5).replace('.',',')} estrelas" aria-pressed="${r.rating===i+.5}"></button><button type="button" class="half-control right" data-rate="${i+1}" aria-label="Avaliar com ${i+1} estrelas" aria-pressed="${r.rating===i+1}"></button></span>`).join('')}</div>`}
function openDetail(id,demo=false){dialogMenu=null;trendOpenId=null;current=items.find(r=>r.id===id);if(!current)return;lastFocus=document.activeElement;drawDetail(demo);$('#detailDialog').showModal();pushDetailState();$('.close-dialog',$('#detailDialog')).focus()}
function seasonsRowHTML(r){const t=r.tmdb?seriesTotals[r.tmdb]:null;const totals=(t&&t.seasons)||{};const hasTotals=Object.keys(totals).length>0;const nums=[...new Set([...(r.seasons||[]).map(x=>Number(x.number)),...Object.keys(totals).map(Number)])].filter(n=>n>=1).sort((a,b)=>a-b);if(!nums.length)return '';const cols=nums.map(n=>{const sd=(r.seasons||[]).find(x=>Number(x.number)===n)||{episodes:[]};const dataEps=sd.episodes||[];const maxData=dataEps.reduce((m,e)=>Math.max(m,Number(e.number)||0),0);const total=Math.max(Number(totals[n])||0,maxData);const eps=[];for(let k=1;k<=total;k++){const e=dataEps.find(x=>Number(x.number)===k);eps.push({number:k,watched:!!e&&e.watched!==false})}const watchedCount=eps.filter(e=>e.watched).length;const head=hasTotals&&total?`${watchedCount} de ${total} marcados`:`${watchedCount} marcados`;return `<div class="season-col" data-season="${n}" data-total="${total}"><div class="season-heading">Temporada ${n}<span>${head}</span></div><div class="episodes">${eps.map(e=>`<button class="episode ${e.watched?'watched':''}" data-episode="${n}:${e.number}" aria-pressed="${e.watched}" aria-label="Temporada ${n}, episódio ${e.number}: ${e.watched?'assistido':'não assistido'}">${e.watched?'✓ ':''}EP ${e.number}</button>`).join('')}</div></div>`}).join('');const note=hasTotals?'Toque nos episódios para marcar ou desmarcar. Os que ainda não foram marcados aparecem sem check.':'Os episódios vêm do backup e não informam o total da série.';return `<div class="seasons-row"><div class="seasons-head"><span class="detail-label">Seu histórico de episódios</span><span class="rating-help">${note}</span></div><div class="seasons-track">${cols}</div></div>`}
function detailAnchorsHTML(r){const links=[['dSinopse','Sinopse'],...(r.type==='tv'?[['dEpisodios','Episódios']]:[]),['dOpiniao','Sua opinião'],...(r.tmdb?[['dSemelhantes','Semelhantes']]:[])];return `<nav class="detail-anchors" aria-label="Seções deste título">${links.map(([id,l])=>`<button type="button" data-anchor="${id}">${l}</button>`).join('')}</nav>`}
const SIMILAR_KEY='cine360-similar-v1';let similarStore={};try{similarStore=JSON.parse(localStorage.getItem(SIMILAR_KEY)||'{}')||{}}catch{similarStore={}}
function similarBlockHTML(r){if(!r.tmdb)return '';const msg=tmdbKey()?'Buscando títulos semelhantes…':'Cole a chave do TMDB em Tendências para ver títulos semelhantes.';return `<section class="similar-block" id="dSemelhantes" aria-label="Mais itens semelhantes"><h3>Mais itens semelhantes</h3><div class="similar-track" data-similar-track="${r.type==='tv'?'tv':'movie'}-${r.tmdb}"><p class="rating-help">${msg}</p></div></section>`}
function similarCardHTML(x){const own=items.find(r=>r.id===x.id&&!r.hidden);const watched=!!own&&['watched','history'].includes(own.status);const inList=!!own&&own.status==='watchlist';const label=watched?'✓ Assistido':inList?'✓ Na lista':'+ Lista';const meta=[x.date?x.date.slice(0,4):'',x.vote?'★ '+Number(x.vote).toFixed(1).replace('.',','):''].filter(Boolean).join(' · ');return `<article class="similar-card"><button type="button" class="similar-poster" data-trend-open="${esc(x.id)}" aria-label="Ver detalhes de ${esc(x.title)}"><img src="${esc(x.poster)}" alt="Capa de ${esc(x.title)}" loading="lazy" referrerpolicy="no-referrer"></button><div class="similar-copy"><strong>${esc(x.title)}</strong><span class="similar-meta">${esc(meta)}</span></div><button type="button" class="similar-add" data-similar-add="${esc(x.id)}" ${watched||inList?'disabled':''}>${label}</button></article>`}
async function hydrateSimilar(root){const key=tmdbKey();if(!key||!root)return;root.querySelectorAll('[data-similar-track]').forEach(async track=>{const k=track.dataset.similarTrack;const cut=k.indexOf('-');const t=k.slice(0,cut),id=k.slice(cut+1);let list=similarStore[k];if(!list||Date.now()-list.at>7*864e5){try{const res=await fetch(`https://api.themoviedb.org/3/${t}/${id}/recommendations?api_key=${encodeURIComponent(key)}&language=pt-BR&page=1`);if(!res.ok)throw new Error('tmdb');const d=await res.json();list={at:Date.now(),items:(d.results||[]).filter(x=>(x.title||x.name)&&x.poster_path).slice(0,12).map(x=>({id:`${t}-${x.id}`,tmdb:x.id,type:t,title:x.title||x.name,poster:`https://image.tmdb.org/t/p/w342${x.poster_path}`,vote:x.vote_average,date:x.release_date||x.first_air_date||'',overview:x.overview||'',backdrop:x.backdrop_path?`https://image.tmdb.org/t/p/w1280${x.backdrop_path}`:''}))};similarStore[k]=list;try{localStorage.setItem(SIMILAR_KEY,JSON.stringify(similarStore))}catch{}}catch{track.innerHTML='<p class="rating-help">Não foi possível carregar os semelhantes agora.</p>';return}}if(!track.isConnected)return;if(!list.items.length){track.innerHTML='<p class="rating-help">Nenhum título semelhante encontrado.</p>';return}list.items.forEach(x=>{extraTrendRows[x.id]={id:x.id,title:x.title,type:x.type,tmdb:x.tmdb,release_date:x.date,synopsis:x.overview,synopsisLanguage:'pt-BR',synopsisSource:`https://www.themoviedb.org/${x.type}/${x.tmdb}`,poster:x.poster,backdrop:x.backdrop,platforms:[],genreIds:[]}});track.innerHTML=list.items.slice(0,6).map(similarCardHTML).join('')})}
