document.addEventListener('click',e=>{const btn=e.target.closest('button');if(!btn)return;if(btn.id==='moreBtn'){const sb=$('.sidebar');const open=!sb.classList.contains('more-open');sb.classList.toggle('more-open',open);btn.setAttribute('aria-expanded',String(open));return}if(trendClick(btn,e))return;if(btn.dataset.cardFavorite){const r=items.find(r=>r.id===btn.dataset.cardFavorite);if(r){update(r.id,{favorite:!r.favorite});render();$(`[data-card-favorite="${r.id}"]`)?.focus()}return}if(btn.hasAttribute('data-suggestion')){selectCatalogTitle(Number(btn.dataset.suggestion));return}if(btn.hasAttribute('data-clear-selection')){clearCatalogSelection(true);closeSuggestions();$('#suggestionStatus').textContent='Digite pelo menos duas letras para buscar no catálogo carregado.';titleInput.focus();return}if(btn.dataset.view){navigate(btn.dataset.view,btn.dataset.type);return}if(selectMode&&btn.dataset.open){selected.has(btn.dataset.open)?selected.delete(btn.dataset.open):selected.add(btn.dataset.open);render();return}if(btn.hasAttribute('data-select-toggle')){selectMode=!selectMode;selected.clear();render();return}if(btn.hasAttribute('data-select-all')){getList().forEach(r=>selected.add(r.id));render();return}if(btn.dataset.bulk){if(btn.dataset.bulk==='clear'){selected.clear();render();return}const st=btn.dataset.bulk;const n=selected.size;selected.forEach(id=>update(id,{status:st}));selected.clear();selectMode=false;toast(`${n} título${n===1?'':'s'} atualizado${n===1?'':'s'}.`);render();return}if(btn.hasAttribute('data-dismiss-backup')){try{localStorage.setItem('cine360-backup-snooze',String(Date.now()+3*864e5))}catch{}render();return}if(btn.dataset.open){openDetail(btn.dataset.open,!!btn.dataset.demo);return}if(btn.dataset.filter){filter=btn.dataset.filter;limit=30;render();return}if(btn.hasAttribute('data-more')){limit+=30;render();return}if(btn.hasAttribute('data-choice')){const pool=items.filter(r=>!r.hidden&&r.status==='watchlist'&&(choiceType==='all'||r.type===choiceType));if(!pool.length){toast('Nenhum título da sua lista para essa escolha.');return}const pick=pool[Math.floor(Math.random()*pool.length)];openDetail(pick.id);return}if(btn.dataset.choiceType){choiceType=btn.dataset.choiceType;render();return}if(btn.hasAttribute('data-draw')){choose();return}if(btn.hasAttribute('data-add')||btn.id==='addBtn'){openAdd();return}if(btn.classList.contains('close-dialog')){btn.closest('dialog').close();return}if(btn.closest('#addForm')&&(btn.dataset.rate||btn.hasAttribute('data-add-clear-rating'))){setAddRating(btn.dataset.rate?Number(btn.dataset.rate):null);return}if(btn.dataset.rate){if(update(current.id,{rating:Number(btn.dataset.rate)})){toast('Avaliação salva.')}$('#ratingContainer').innerHTML=ratingPicker(current);setRatingText(current);render();return}if(btn.hasAttribute('data-clear-rating')){update(current.id,{rating:null});$('#ratingContainer').innerHTML=ratingPicker(current);setRatingText(current);render();return}if(btn.hasAttribute('data-favorite')){update(current.id,{favorite:!current.favorite});btn.textContent=current.favorite?'♥ Favoritado':'♡ Favoritar';render();return}if(btn.hasAttribute('data-edit-details')){$('#editDetails').hidden=!$('#editDetails').hidden;return}if(btn.hasAttribute('data-save-details')){const poster=$('#posterInput').value.trim();if(poster&&!safeURL(poster)){toast('Use uma URL de imagem começando com https://');return}const ok=update(current.id,{synopsis:$('#synopsisInput').value.trim(),synopsisSource:null,poster:poster||current.poster});drawDetail();render();if(ok)toast('Detalhes salvos.');return}if(btn.dataset.episode){const [season,episode]=btn.dataset.episode.split(':').map(Number);const seasons=structuredClone(current.seasons||[]);let sObj=seasons.find(x=>Number(x.number)===season);if(!sObj){sObj={number:season,episodes:[]};seasons.push(sObj);seasons.sort((a,b)=>a.number-b.number)}let ep=sObj.episodes.find(x=>Number(x.number)===episode);if(!ep){ep={number:episode,addedDate:new Date().toISOString(),watched:false};sObj.episodes.push(ep);sObj.episodes.sort((a,b)=>a.number-b.number)}if(ep){ep.watched=ep.watched===false;update(current.id,{seasons});btn.classList.toggle('watched',ep.watched);btn.setAttribute('aria-pressed',String(ep.watched));btn.setAttribute('aria-label',`Temporada ${season}, episódio ${episode}: ${ep.watched?'assistido':'não assistido'}`);btn.textContent=(ep.watched?'✓ ':'')+'EP '+episode;drawDetail();render()}return}if(btn.dataset.deleteCollection){const name=btn.dataset.deleteCollection;const affected=items.filter(r=>(r.collections||[]).includes(name));if(!confirm(`Excluir a coleção “${labels[name]||name}”? Os ${affected.length} títulos continuam na sua biblioteca; só a coleção é removida.`))return;affected.forEach(r=>update(r.id,{collections:(r.collections||[]).filter(c=>c!==name)}));navigate('home');toast('Coleção excluída. Os títulos continuam na sua biblioteca.');return}if(btn.dataset.wish){addWish(btn.dataset.wish);return}if(btn.dataset.heroStep){heroIndex+=Number(btn.dataset.heroStep);heroElapsed=0;render();return}if(btn.hasAttribute('data-hide')){if(confirm('Remover este título da sua biblioteca? O histórico original continua preservado no arquivo.')){update(current.id,{hidden:true});$('#detailDialog').close();render()}return}if(btn.id==='backupBtn'||btn.hasAttribute('data-backup')){backup();return}if(btn.hasAttribute('data-cal-day-close')){calDay=null;render();return}if(btn.dataset.calDay){calDay=calDay===Number(btn.dataset.calDay)?null:Number(btn.dataset.calDay);render();return}if(btn.dataset.month){calDay=null;month=new Date(month.getFullYear(),month.getMonth()+Number(btn.dataset.month),1);render();return}if(btn.dataset.calfilter){calendarFilter=btn.dataset.calfilter;render();return}});
document.addEventListener('change',e=>{if(e.target.name==='readStatus')addRatingUI();if(e.target.id==='genreFilter'){genreFilter=e.target.value;limit=30;render()}if(e.target.id==='sort'){sort=e.target.value;render()}if(e.target.id==='statusSelect'){update(current.id,{status:e.target.value});render();toast('Status atualizado.')}if(e.target.id==='prioritySelect'){update(current.id,{priority:Number(e.target.value)});render();toast('Prioridade atualizada.')}if(e.target.id==='noteInput'){update(current.id,{notes:e.target.value});}if(e.target.id==='platform'){calendar.platform=e.target.value;render();$('#platform').value=calendar.platform;}});
