const isReprint=note=>/Relançamento|Evento|Transmissão|Restaurado/i.test(note||'');
function upcomingAll(){const today=new Date().toISOString().slice(0,10);const rows=new Map();(window.CINE360_DATA.catalog||[]).forEach(r=>{const d=(r.release_date||'').slice(0,10);if(d>=today)rows.set(normalized(r.title)+'|'+r.type,{id:r.id,title:r.title,type:r.type,release_date:d,poster:r.poster||'',backdrop:r.backdrop||'',synopsis:r.synopsis||'',synopsisSource:r.synopsisSource||null,synopsisLanguage:r.synopsisLanguage,tmdb:r.tmdb,genreIds:r.genreIds||[],kind:''})});releases.forEach(([day,type,title,note])=>{if(isReprint(note))return;const d=`2026-10-${pad2(day)}`;if(d<today)return;const tv=type==='stream'&&/Série|Temporada|Anime/.test(note||'');const kindType=tv?'tv':'movie';const key=normalized(title)+'|'+kindType;const catalogHit=[...rows.values()].find(x=>normalized(x.title)===normalized(title));if(catalogHit){catalogHit.kind=type==='stream'?'Streaming':'Cinema';return}if(!rows.has(key))rows.set(key,{id:'cal-'+normalized(title).replace(/[^a-z0-9]+/g,'-'),title,type:kindType,release_date:d,poster:'',backdrop:'',synopsis:'',genreIds:[],kind:type==='stream'?'Streaming':'Cinema',note:note||''})});return [...rows.values()].sort((a,b)=>a.release_date.localeCompare(b.release_date)||a.title.localeCompare(b.title,'pt-BR'))}
function greetingLine(){const N='<span class="hi-name">Eduardo</span>';const h=Number(new Intl.DateTimeFormat('en-US',{hour:'numeric',hour12:false,timeZone:'America/Sao_Paulo'}).formatToParts(new Date()).find(p=>p.type==='hour').value)%24;if(h>=5&&h<=11)return `Bom dia, ${N}!`;if(h>=12&&h<=17)return `Boa tarde, ${N}!`;if(h>=18)return `Boa noite, ${N}!`;return `Madrugando, ${N}?`}
function upcomingRows(){return upcomingAll().map(r=>{const k=normalized(r.title);const m=trendMeta[k]||{};const poster=r.poster||trendPosters[k]||'';if(r.tmdb||!m.tmdb)return poster===r.poster?r:{...r,poster};return {...r,poster,tmdb:m.tmdb,type:m.type||r.type}})}
let upHydrating=false;
async function hydrateUpcomingPosters(){const key=tmdbKey();if(!key||upHydrating)return;const queue=upcomingAll().filter(r=>!r.poster&&!r.tmdb&&trendPosters[normalized(r.title)]===undefined).slice(0,80);if(!queue.length)return;upHydrating=true;let changed=false;const worker=async()=>{while(queue.length){const r=queue.shift();const k=normalized(r.title);try{const res=await fetch(`https://api.themoviedb.org/3/search/multi?api_key=${encodeURIComponent(key)}&language=pt-BR&query=${encodeURIComponent(r.title)}`);if(!res.ok)return;const data=await res.json();const hit=(data.results||[]).find(x=>(x.media_type==='movie'||x.media_type==='tv')&&x.poster_path);trendPosters[k]=hit?`https://image.tmdb.org/t/p/w500${hit.poster_path}`:'';trendMeta[k]=hit?{overview:hit.overview||'',tmdb:hit.id,type:hit.media_type}:{overview:'',tmdb:null,type:''};changed=true}catch{return}}};try{await Promise.all(Array.from({length:6},worker))}finally{upHydrating=false}if(changed){try{localStorage.setItem(TREND_POSTER_KEY,JSON.stringify(trendPosters));localStorage.setItem('cine360-trend-meta',JSON.stringify(trendMeta))}catch{}if(view==='upcoming')render()}}
