let fanIds=[];
function fanPool(){const live=items.filter(r=>!r.hidden&&r.status==='watchlist');const withPoster=live.filter(r=>safeImageURL(r.poster));return withPoster.length>=3?withPoster:live}
function fanHTML(){const pool=fanPool();fanIds=fanIds.filter(id=>pool.some(r=>r.id===id));const free=pool.filter(r=>!fanIds.includes(r.id));while(fanIds.length<Math.min(3,pool.length)&&free.length){fanIds.push(free.splice(Math.floor(Math.random()*free.length),1)[0].id)}return fanIds.map(id=>artwork(pool.find(r=>r.id===id))).join('')}
function spinFan(){const fan=document.querySelector('[data-fan]');const pool=fanPool();if(!fan||pool.length<4||document.hidden||document.querySelector('dialog[open]'))return;[0,1,2].forEach(k=>setTimeout(()=>{const slot=fan.children[k];if(!slot||!fanIds[k])return;const used=new Set(fanIds);const free=pool.filter(r=>!used.has(r.id));if(!free.length)return;const pick=free[Math.floor(Math.random()*free.length)];fanIds[k]=pick.id;const tpl=document.createElement('template');tpl.innerHTML=artwork(pick).trim();const el=tpl.content.firstElementChild;el.classList.add('fan-flip');slot.replaceWith(el);fixImages(fan)},k*230))}
