async function loadTmdbNotes(root){const key=tmdbKey();if(!key||!root)return;root.querySelectorAll('[data-tmdb-note]').forEach(async el=>{const k=`${el.dataset.noteType}-${el.dataset.noteId}`;if(tmdbRatings[k]!==undefined)return;try{const res=await fetch(`https://api.themoviedb.org/3/${el.dataset.noteType}/${el.dataset.noteId}?api_key=${encodeURIComponent(key)}&language=pt-BR`);if(res.status===404){tmdbRatings[k]={avg:null};return}if(!res.ok)return;const d=await res.json();tmdbRatings[k]={avg:d.vote_count>0?Number(d.vote_average):null};try{localStorage.setItem(RATING_KEY,JSON.stringify(tmdbRatings))}catch{}if(el.isConnected&&tmdbRatings[k].avg){el.textContent=`TMDB ★ ${Number(tmdbRatings[k].avg).toFixed(1).replace('.',',')}`;el.hidden=false}}catch{}})}
