const trailerPrefetching=new Set();
function prefetchTrailerFor(r){if(!r||!r.tmdb||!tmdbKey())return;const type=r.type==='tv'?'tv':'movie';const k=`${type}-${r.tmdb}`;if(trailerCache[k]!==undefined||trailerPrefetching.has(k))return;trailerPrefetching.add(k);findTrailer(type,r.tmdb).catch(()=>{}).finally(()=>trailerPrefetching.delete(k))}
