async function findTrailer(type,id){const cacheKey=`${type}-${id}`;if(trailerCache[cacheKey]!==undefined)return trailerCache[cacheKey];const k=tmdbKey();if(!k)return null;let found=null;for(const lang of ['pt-BR','en-US']){const res=await fetch(`https://api.themoviedb.org/3/${type}/${id}/videos?api_key=${encodeURIComponent(k)}&language=${lang}`);if(!res.ok)throw new Error('tmdb');const list=((await res.json()).results||[]).filter(v=>v.site==='YouTube'&&v.key&&(v.type==='Trailer'||v.type==='Teaser'));if(list.length){list.sort((a,b)=>(Number(!!b.official)-Number(!!a.official))||(Number(b.type==='Trailer')-Number(a.type==='Trailer')));found=list[0].key;break}}trailerCache[cacheKey]=found;try{localStorage.setItem(TRAILER_KEY,JSON.stringify(trailerCache))}catch{}return found}
const TOP_KEY='cine360-top10-v4';let top10Busy=false,top10Retry=0;
const top10Day=()=>new Date().toLocaleDateString('en-CA',{timeZone:'America/Sao_Paulo'});
function top10Cached(){try{const c=JSON.parse(localStorage.getItem(TOP_KEY)||'null');return c&&c.at&&Date.now()-c.at<LIVE_TTL?c:null}catch{return null}}
function top10Col(list,label){return `<div class="top10-col"><h2 class="up-type">${label}<span>${list.length} títulos</span></h2><ol class="top10-grid">${list.map((t,i)=>`<li class="top10-item"><button type="button" class="top10-open" data-top10="${t.type}-${t.id}" aria-label="${esc(t.title)}, nota ${t.avg.toFixed(1)}"><div class="poster-art top10-poster">${t.poster?`<img src="${esc(t.poster)}" alt="Capa de ${esc(t.title)}" loading="eager" decoding="async" referrerpolicy="no-referrer" data-image>`:`<div class="poster-fallback"><span>Maratonenzo</span>${esc(t.title)}</div>`}<span class="top10-rank">${i+1}</span></div><div class="top10-copy"><strong>${esc(t.title)}</strong><span class="pub-rating">TMDB ★ ${t.avg.toFixed(1).replace('.',',')}</span><small>${esc(t.year||'')}</small></div></button></li>`).join('')}</ol></div>`}
function top10HTML(){const head=header('Top 10 da semana','Os títulos em alta no TMDB nesta semana, ordenados pela nota média.');if(!tmdbKey())return `<section class="section top10">${head}<p class="demo-notice tmdb-hint">Cole sua chave do TMDB na página <button type="button" class="text-btn" data-view="trends">Tendências</button> para ver o Top 10 da semana.</p></section>`;const c=top10Cached();if(!c)return `<section class="section top10">${head}<div class="skeleton-row" aria-hidden="true">${'<span class="skeleton-card"></span>'.repeat(6)}</div><p class="sr-only">Buscando o Top 10 no TMDB…</p></section>`;return `<section class="section top10">${head}<div class="top10-cols">${c.movie.length?top10Col(c.movie,'Filmes'):'<p class="muted">Nenhum filme com votos suficientes esta semana.</p>'}${c.tv.length?top10Col(c.tv,'Séries'):'<p class="muted">Nenhuma série com votos suficientes esta semana.</p>'}</div></section>`}
async function hydrateTop10(){const key=tmdbKey();if(!key||top10Busy||top10Cached()||Date.now()<top10Retry)return;top10Busy=true;try{const get=async(type,page)=>{const res=await fetch(`https://api.themoviedb.org/3/trending/${type}/week?api_key=${encodeURIComponent(key)}&language=pt-BR&page=${page}`);if(!res.ok)throw new Error('tmdb');return (await res.json()).results||[]};const disc=async(type,page)=>{const dk=type==='movie'?'primary_release_date':'first_air_date';const res=await fetch(`https://api.themoviedb.org/3/discover/${type}?api_key=${encodeURIComponent(key)}&language=pt-BR&sort_by=popularity.desc&${dk}.gte=2025-01-01&without_genres=16,10762&vote_count.gte=50&page=${page}`);if(!res.ok)throw new Error('tmdb');return (await res.json()).results||[]};const pick=async type=>{const [a,b,c,d,e,f]=await Promise.all([get(type,1),get(type,2),get(type,3),disc(type,1),disc(type,2),disc(type,3)]);return [...a,...b,...c,...d,...e,...f].filter((r,i,arr)=>arr.findIndex(x=>x.id===r.id)===i).filter(r=>r.poster_path&&Number(r.vote_count)>=50&&Number((r.release_date||r.first_air_date||'').slice(0,4))>=2025&&!(r.genre_ids||[]).some(g=>g===16||g===10762)&&r.original_language!=='ja').sort((x,y)=>y.vote_average-x.vote_average).slice(0,10).map(r=>({id:r.id,type,title:r.title||r.name||'',poster:`https://image.tmdb.org/t/p/w500${r.poster_path}`,avg:Number(r.vote_average),year:(r.release_date||r.first_air_date||'').slice(0,4),overview:r.overview||''}))};const [movie,tv]=await Promise.all([pick('movie'),pick('tv')]);try{localStorage.setItem(TOP_KEY,JSON.stringify({at:Date.now(),day:top10Day(),movie,tv}))}catch{}top10Busy=false;render()}catch{top10Retry=Date.now()+600000;top10Busy=false}}
let tmdbRatings={},ratingHydrating=false;const RATING_KEY='cine360-tmdb-ratings';
try{tmdbRatings=JSON.parse(localStorage.getItem(RATING_KEY)||'{}')||{}}catch{tmdbRatings={}}
const ratingKeyOf=r=>(r.type==='tv'?'tv':'movie')+'-'+r.tmdb;
function pubRatingValue(r){if(!r||!r.tmdb)return null;const v=tmdbRatings[ratingKeyOf(r)];return v&&v.avg?v.avg:null}
function pubRatingHTML(r){const v=pubRatingValue(r);return v?`<span aria-hidden="true">·</span><span class="pub-rating" title="Média pública no TMDB">TMDB ★ ${v.toFixed(1).replace('.',',')}</span>`:''}
function ratingTargets(){const seen=new Map();const add=r=>{if(!r||!r.tmdb)return;const k=ratingKeyOf(r);if(!seen.has(k))seen.set(k,{k,type:r.type==='tv'?'tv':'movie',id:r.tmdb})};items.filter(r=>!r.hidden).forEach(add);trendAll().forEach(add);upcomingRows().forEach(add);return [...seen.values()].filter(t=>tmdbRatings[t.k]===undefined)}
async function hydrateRatings(){const key=tmdbKey();if(!key||ratingHydrating)return;const todo=ratingTargets().slice(0,400);if(!todo.length)return;ratingHydrating=true;let changed=false,last=0,stop=false;const save=()=>{try{localStorage.setItem(RATING_KEY,JSON.stringify(tmdbRatings))}catch{}};const queue=[...todo];const worker=async()=>{while(queue.length&&!stop){const t=queue.shift();try{const res=await fetch(`https://api.themoviedb.org/3/${t.type}/${t.id}?api_key=${encodeURIComponent(key)}&language=pt-BR`);if(res.status===404){tmdbRatings[t.k]={avg:null};changed=true}else if(!res.ok){stop=true;break}else{const d=await res.json();tmdbRatings[t.k]={avg:d.vote_count>0?Number(d.vote_average):null};changed=true}}catch{stop=true;break}if(Date.now()-last>2500){last=Date.now();save();render()}}};try{await Promise.all(Array.from({length:6},worker))}finally{ratingHydrating=false}if(changed){save();render()}}
