document.addEventListener('submit',async e=>{const f=e.target.closest('[data-tmdb-form]');if(!f)return;e.preventDefault();const key=String(new FormData(f).get('key')||'').trim();if(!key)return;const btn=f.querySelector('button[type=submit]');const showError=msg=>{let n=f.querySelector('.tmdb-notice');if(!n){n=document.createElement('p');n.className='tmdb-notice';f.appendChild(n)}n.textContent=msg};if(btn)btn.disabled=true;let status=0;try{const res=await fetch(`https://api.themoviedb.org/3/configuration?api_key=${encodeURIComponent(key)}`);status=res.status}catch{status=0}finally{if(btn)btn.disabled=false}if(status===401||status===403){showError('Chave inválida. Use a chave API v3 do TMDB (a "API Key"), não o token de leitura.');return}try{localStorage.setItem(TMDB_KEY_STORE,key)}catch{toast('Não foi possível salvar a chave neste navegador.');return}toast(status===200?'Chave salva e validada. Buscando dados…':'Chave salva. Não consegui validar agora.');render()});

