let swipe=null,swipeBlock=false;
const swipeOn=()=>window.matchMedia('(max-width:1024px)').matches;
document.addEventListener('touchstart',e=>{const card=e.target.closest('.poster-card');if(!card||selectMode||e.touches.length!==1||!swipeOn()){swipe=null;return}const t=e.touches[0];swipe={card,x:t.clientX,y:t.clientY,dx:0,on:false,id:card.querySelector('[data-open]')?.dataset.open}},{passive:true});
document.addEventListener('touchmove',e=>{if(!swipe)return;const t=e.touches[0];const dx=t.clientX-swipe.x,dy=t.clientY-swipe.y;if(!swipe.on){if(Math.abs(dy)>10&&Math.abs(dy)>Math.abs(dx)){swipe=null;return}if(Math.abs(dx)<12)return;swipe.on=true}swipe.dx=dx;const shift=Math.max(-110,Math.min(110,dx));swipe.card.style.transition='none';swipe.card.style.transform=`translateX(${shift*0.7}px)`;swipe.card.dataset.swipe=dx>0?'right':'left'},{passive:true});
const endSwipe=cancelled=>{if(!swipe)return;const s=swipe;swipe=null;if(!s.on)return;s.card.style.transition='transform .25s ease';s.card.style.transform='';setTimeout(()=>{delete s.card.dataset.swipe},250);swipeBlock=true;setTimeout(()=>{swipeBlock=false},400);if(cancelled||!s.id)return;const r=items.find(x=>x.id===s.id);if(!r)return;const target=s.dx>90?'watchlist':s.dx<-90?'watched':null;if(!target)return;if(r.status===target){toast(`${r.title} já está em "${statusLabels[target]}".`);return}update(r.id,{status:target});render();toast(`${r.title}: ${statusLabels[target]}.`)};
document.addEventListener('touchend',()=>endSwipe(false));
document.addEventListener('touchcancel',()=>endSwipe(true));
document.addEventListener('click',e=>{if(!swipeBlock)return;e.stopPropagation();e.preventDefault();swipeBlock=false},true);

