function rateWord(v){v=Number(v)||0;if(!v)return 'Arraste ou toque para avaliar';if(v<=2)return 'Péssimo';if(v<=4)return 'Ruim';if(v<=5.5)return 'Mediano';if(v<=7)return 'Bom';if(v<=8.5)return 'Ótimo';if(v<=9.5)return 'Excelente';return 'Obra-prima'}
function rateSliderHTML(v){v=Number(v)||0;return `<div class="rate-slider" data-rate-slider data-value="${v}"><div class="rate-stars"><div class="rate-row" aria-hidden="true">${Array.from({length:10},(_,i)=>`<span class="rate-star"><span class="rate-star-fill" style="width:${Math.max(0,Math.min(1,v-i))*100}%"></span></span>`).join('')}</div><input class="rate-input" type="range" min="0" max="10" step="0.5" value="${v}" aria-label="Sua nota, de 0 a 10" aria-valuetext="${v?String(v).replace('.',',')+' de 10':'sem nota'}"></div><div class="rate-readout"><span class="rate-num" data-rate-num>${v?v.toFixed(1):'—'}</span><span class="rate-word" data-rate-word>${rateWord(v)}</span><button type="button" class="rate-clear" data-slider-clear${v?'':' hidden'}>Limpar nota</button></div></div>`}
function paintRateSlider(sl,v,preview){v=Math.max(0,Math.min(10,Number(v)||0));$$('.rate-star-fill',sl).forEach((f,i)=>{f.style.width=Math.max(0,Math.min(1,v-i))*100+'%'});const n=sl.querySelector('[data-rate-num]');if(n)n.textContent=v?v.toFixed(1):'—';const w=sl.querySelector('[data-rate-word]');if(w)w.textContent=rateWord(v);sl.classList.toggle('is-preview',!!preview);const inp=sl.querySelector('.rate-input');if(inp&&!preview){inp.value=v;inp.setAttribute('aria-valuetext',v?String(v).replace('.',',')+' de 10':'sem nota')}}
function rateFromPointer(sl,x){const row=sl.querySelector('.rate-row');const r=row.getBoundingClientRect();const f=(x-r.left)/r.width;if(f<=0)return 0.5;return Math.max(0.5,Math.min(10,Math.ceil(f*20-1e-6)/2))}
function commitSliderRating(sl,v){v=Math.max(0,Math.min(10,Number(v)||0));sl.dataset.value=v;paintRateSlider(sl,v,false);const clr=sl.querySelector('[data-slider-clear]');if(clr)clr.hidden=!v;if(current){if(update(current.id,{rating:v||null}))toast(v?`Nota ${v.toFixed(1).replace('.',',')} salva.`:'Nota removida.');setRatingText(current);render();return}if(trendOpenId){if(v){rateTrend(trendOpenId,v)}else{const rid=items.find(x=>x.id===trendOpenId)?.id;if(rid){update(rid,{rating:null});toast('Nota removida.')}drawTrend(trendOpenId);render()}}}
