document.addEventListener('pointermove',e=>{if(rateDrag&&e.pointerId===rateDrag.id){rateDrag.v=rateFromPointer(rateDrag.sl,e.clientX);paintRateSlider(rateDrag.sl,rateDrag.v,true);return}if(e.pointerType!=='mouse')return;const stars=e.target.closest('.rate-stars');if(!stars)return;const sl=stars.closest('[data-rate-slider]');paintRateSlider(sl,rateFromPointer(sl,e.clientX),true)});
